contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public function with all logic
    function run(uint256 wagerSend) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wagerSend)); require(wagerSend <= 1000000000000000000000000000000);
        // require we have funds to send the wager
        require(address(this).balance >= wagerSend);

        // Try to open the contract to the public; ignore if it reverts
        c.OpenToThePublic(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {} else {
        }

        // Attempt to place a wager by sending exactly wagerSend
        bool wagerReverted;
        c.wager{value: wagerSend}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            wagerReverted = true;
        } else {
            wagerReverted = false;
        }

        // Attempt to call play()
        bool playReverted;
        c.play(); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            playReverted = true;
        } else {
            playReverted = false;
        }

        // Assert: if play succeeded then we no longer have an active wager
        assert(playReverted || c.hasPlayerWagered(address(this)) == false);
    }

    receive() external payable {}
}

